export function generateResourceID(r="#"){function idPart(){return Math.floor(65536*(1+Math.random())).toString(16).substring(1)}return r+idPart()+idPart()+"-"+idPart()+"-"+idPart()+"-"+idPart()+"-"+idPart()+idPart()+idPart()}